scripts.src:
[ -n "$1" ] || { echo 'Give a file, for example: tk-top-ips auth.log'; exit 2; }
f="$1"
grep -oE '([0-9]{1,3}\.){3}[0-9]{1,3}' "$f" | sort | uniq -c | sort -rn | head -n "${2:-10}"

d=${1:-.}
o=${2:-/tmp/evidence.sha256}
find "$d" -type f | sort | while IFS= read -r p; do sha256sum "$p"; done > "$o"
echo "$(wc -l < "$o") files hashed into $o"
head -n 5 "$o"

[ -n "$1" ] || { echo 'Give a range, for example: tk-sweep 10.20.0.0/24'; exit 2; }
r="$1"
nmap -sn "$r"

[ -n "$1" ] || { echo 'Give a host, for example: tk-ports 10.20.0.5'; exit 2; }
h="$1"
nmap -sV "$h"
